Action.Str:
String p = tasker.getVariable("par1");
String i = tasker.getVariable("cl_image_uri");
String t = tasker.getVariable("cl_text");
boolean emptyP = p == null || p.length() == 0;
boolean emptyI = i == null || i.length() == 0;
boolean emptyT = t == null || t.length() == 0;
tasker.setVariable("need_clipboard", emptyP && emptyI && emptyT ? "1" : "0");

import android.net.Uri;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.InputStream;
import java.util.concurrent.TimeUnit;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.json.JSONObject;

String serverUrl = tasker.getVariable("clip_server_url");
String authToken = tasker.getVariable("clip_auth_token");
if (serverUrl != null) serverUrl = serverUrl.trim().replaceAll("/+$", "");
if (authToken != null) authToken = authToken.trim();

String taskImage = tasker.getVariable("par1");
String eventImage = tasker.getVariable("cl_image_uri");
String text = tasker.getVariable("cl_text");
String html = tasker.getVariable("cl_html_text");
if (taskImage == null) taskImage = "";
if (eventImage == null) eventImage = "";
if (text == null) text = "";
if (html == null) html = "";

String imageSource = taskImage.length() > 0 ? taskImage : eventImage;
String textSource = text.length() > 0 ? text : html;
String message = "";
Response response = null;
InputStream input = null;

try {
    if (serverUrl == null || serverUrl.length() == 0 || serverUrl.startsWith("__CLIP_")) {
        message = "配置错误：未配置 Server URL";
    } else if (!(serverUrl.startsWith("http://") || serverUrl.startsWith("https://"))) {
        message = "配置错误：Server URL 必须以 http:// 或 https:// 开头";
    } else if (authToken == null || authToken.length() == 0 || authToken.startsWith("__CLIP_")) {
        message = "配置错误：未配置 Device Token";
    } else if (imageSource.length() == 0 && textSource.length() == 0) {
        message = "剪贴板为空或不包含可上传的文本/图片";
    } else {
        OkHttpClient client = new OkHttpClient.Builder()
            .connectTimeout(15, TimeUnit.SECONDS)
            .readTimeout(30, TimeUnit.SECONDS)
            .build();

        RequestBody body;
        String kind;
        if (imageSource.length() > 0) {
            kind = "图片";
            MediaType binaryType = MediaType.parse("application/octet-stream");
            if (imageSource.startsWith("content://")) {
                input = context.getContentResolver().openInputStream(Uri.parse(imageSource));
                if (input == null) throw new Exception("无法打开剪贴板图片 URI");
                ByteArrayOutputStream output = new ByteArrayOutputStream();
                byte[] buffer = new byte[8192];
                int count;
                while ((count = input.read(buffer)) != -1) output.write(buffer, 0, count);
                byte[] bytes = output.toByteArray();
                if (bytes.length == 0) throw new Exception("剪贴板图片为空");
                body = RequestBody.create(binaryType, bytes);
            } else {
                String path = imageSource.startsWith("file://") ? imageSource.substring(7) : imageSource;
                File file = new File(path);
                if (!file.isFile()) throw new Exception("图片文件不存在或无法读取：" + path);
                body = RequestBody.create(binaryType, file);
            }
        } else {
            kind = "文本";
            JSONObject json = new JSONObject();
            json.put("kind", "text");
            json.put("content", textSource);
            body = RequestBody.create(MediaType.parse("application/json; charset=utf-8"), json.toString());
        }

        Request request = new Request.Builder()
            .url(serverUrl + "/api/clipboard/upload")
            .header("Authorization", "Bearer " + authToken)
            .header("Accept", "application/json")
            .post(body)
            .build();

        response = client.newCall(request).execute();
        int status = response.code();
        ResponseBody responseBody = response.body();
        String responseText = responseBody == null ? "" : responseBody.string();

        if (status >= 200 && status < 300) {
            message = kind + "上传成功";
        } else {
            String detail = responseText;
            try {
                JSONObject errorJson = new JSONObject(responseText);
                String parsed = errorJson.optString("detail", "");
                if (parsed.length() > 0) detail = parsed;
            } catch (Exception ignored) {
            }
            message = kind + "上传失败（HTTP " + status + "）" + (detail.length() > 0 ? "：" + detail : "");
        }
    }
} catch (Exception error) {
    String detail = error.getMessage();
    if (detail == null || detail.length() == 0) detail = error.getClass().getSimpleName();
    message = "上传失败：" + detail;
} finally {
    try { if (input != null) input.close(); } catch (Exception ignored) {}
    if (response != null) response.close();
}

tasker.setVariable("result_message", message);
